1	#!/usr/bin/env node
2	// SessionStart step: state, in one line, WHAT ACTUALLY LOADED this session —
3	// which repo, the active packs, the token weight of the prose injected, the guards
4	// and checks they arm, the skills mounted (the ones the hooks load on their own
5	// apart from the rest), plus whatever facet an active pack contributes about
6	// itself. Its stdout becomes session context, and it carries the directive that
7	// makes the session open with the line, so the person in front of it sees the
8	// load stated back rather than having to trust that it happened.
9	//
10	// WHY IT IS NOT THE ORCHESTRATOR'S FOOTER. That footer reports the MACHINERY:
11	// which steps ran and which crashed. This reports the VOLUME: how much guidance
12	// is in the window and how much of it is armed as checks. The two answer
13	// different questions and neither substitutes for the other — a session where
14	// every step ran and nothing was declared looks identical from the footer alone.
15	//
16	// RUNS LAST, after the steps whose work it counts (the skill mount), so it describes
17	// the session that exists rather than the one about to. The prose it weighs no longer
18	// arrives through this hook at all — it rides CLAUDE.md since #807 — but the weight is
19	// still this line's to state, because the cost lands in the same context window and a
20	// session that cannot see it has no way to notice the corpus growing.
21	//
22	// Core names no pack to get a pack-specific facet. A pack that has one states it
23	// on the FACET CHANNEL — a `CLAUDINITE-FACET:` line from its session-start step,
24	// collected by the step runner (engine/pack_loader/run-pack-session-start.mjs)
25	// into the file `CLAUDINITE_SESSION_FACETS` names — and this step appends what it
26	// finds there. The channel rides the step because the facts worth stating are the
27	// ones a pack had to COMPUTE: a static count is already in prose the reader has.
28	//
29	// Fails soft to silence, and exits 0 always — a non-zero exit makes Claude Code
30	// DISCARD the orchestrator's whole stdout, including the steps that did work.
31	import { readFileSync, existsSync } from 'node:fs';
32	import { join, dirname } from 'node:path';
33	import { fileURLToPath } from 'node:url';
34	import { settingsPath } from '../settings-file.mjs';
35	
36	import { spawnSync } from 'node:child_process';
37	import { countWords, estimateTokens } from './token-estimate.mjs';
38	
39	// The prose is reported in TOKENS because that is the unit of the cost it
40	// imposes — a context window, not a disk. The estimate goes through WORDS at the
41	// ratio token-estimate.mjs states. Rounded to the hundred and shown in thousands
42	// (`14.3k`), because a session summary is a sense of scale, not an accounting.
43	const TOKEN_ROUNDING = 100;
44	const plural = (n, one, many = `${one}s`) => `${n.toLocaleString('en-US')} ${n === 1 ? one : many}`;
45	const thousands = (n) => (n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(n));
46	
47	// Which repo this is, as `owner/repo`: the checkout's own origin remote, or the
48	// Actions environment naming it. Neither known is no facet — the line never guesses
49	// a name, and a directory name is not one.
50	function repoName(projectRoot) {
51	  const fromEnv = process.env.GITHUB_REPOSITORY;
52	  const git = spawnSync('git', ['remote', 'get-url', 'origin'], { cwd: projectRoot, encoding: 'utf8' });
53	  const url = git.status === 0 ? git.stdout.trim() : '';
54	  const m = /[:/]([^/:]+)\/([^/]+?)(?:\.git)?\/?$/.exec(url);
55	  if (m) return `${m[1]}/${m[2]}`;
56	  return typeof fromEnv === 'string' && fromEnv.includes('/') ? fromEnv : null;
57	}
58	
59	try {
60	  const loaderDir = dirname(fileURLToPath(import.meta.url)); // <corpus>/engine/pack_loader
61	  const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
62	
63	  let declared = [];
64	  const configPath = settingsPath(projectRoot);
65	  if (existsSync(configPath)) {
66	    const raw = JSON.parse(readFileSync(configPath, 'utf8'));
67	    if (Array.isArray(raw.packs)) declared = raw.packs;
68	  }
69	
70	  const { loadPacks, isActive, bundledSkillSources } = await import(join(loaderDir, 'pack-registry.mjs'));
71	  const packs = await loadPacks({ localRoot: projectRoot, session: true });
72	  // A pack COPIED for the person in this session counts like any other that loaded: its
73	  // rules reach the window through the same import as the rest, so one number covers all
74	  // of it. Held out, it needed a second number under a second name for prose that loads
75	  // identically - and a reader with only the first was told a corpus smaller than theirs.
76	  const active = packs.filter((pack) => isActive(pack, { packs: declared }));
77	  // Nothing active means this repo runs no Claudinite. Nothing loaded, so there
78	  // is nothing to state — the same silence the prose injector keeps.
79	  if (!active.length) process.exit(0);
80	
81	  // The prose the injector actually emits: each active pack's own file, resolved
82	  // off the pack's directory, trimmed the way the injector trims it. The routing
83	  // table and the directory pointer are the injector's framing rather than a
84	  // pack's rules, so they are not counted here.
85	  const wordsByPack = new Map();
86	  for (const pack of active) {
