    plural(active.length, 'pack'),
    `${thousands(tokens)} context tokens`,
    plural(guards, 'guard'),
    plural(checks, 'code check'),
    plural(autoTrigger, 'auto-trigger skill'),
    plural(regular, 'regular skill'),
