  }
  if (file.notEvaluated.length) {
    const short = file.notEvaluated.slice(0, 20);
    out.push('', `## Not evaluated - ${file.notEvaluated.length}`, '');
    out.push(table(short.map((n) => [
      `\`${n.subject}\``, `\`${n.rule}\``, n.name, n.need ?? '-', n.have ?? '*not recorded*',
