  const valid = {
    id: 'demo',
    ruleRoutingGuidance: { belongs: 'a b c', excludes: 'd e f' },
  };
  assert.deepEqual(validateManifest({ ...valid, seedOps: [{ template: 'stubs/x.yml', dest: '.github/x.yml' }] }), []);
