  for (const bad of [[{ template: 'x' }], [{ dest: 'y' }], ['x'], [null], 'x']) {
    assert.match(validateManifest({ ...valid, seedOps: bad }).map((e) => e.what).join(' '), /"seedOps" is not a valid value/, JSON.stringify(bad));
  }
});

