import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  CHARS_PER_TOKEN, countChars, countWords, estimateTokens, estimateTokensOf,
} from '../../engine/pack_loader/token-estimate.mjs';

// The band a real tokenizer measured over this repo's own corpus: `cl100k_base`
// answers 4.16 chars per token across the pack prose CLAUDE.md imports and 4.27
// across the skill bodies. The band, not the digit, is the assertion — a ratio moved
// outside what was measured is a ratio that has stopped describing this corpus, and
// the way back in is another tokenizer run, not a nudge until this passes.
test('the ratio stays inside the band a tokenizer measured for this corpus', () => {
  assert.ok(CHARS_PER_TOKEN >= 4.0 && CHARS_PER_TOKEN <= 4.4,
    `${CHARS_PER_TOKEN} chars per token is outside the 4.0–4.4 the corpus measured; re-measure before moving it`);
});

test('the estimate is characters over that ratio, and text is counted by its characters', () => {
  // Stated as the ratio's own arithmetic rather than as a figure taken off a run:
  // 4,200 characters is 1,000 tokens at 4.2, and the assertion moves with the constant.
  const text = 'x'.repeat(4200);
  assert.equal(countChars(text), 4200);
  assert.equal(estimateTokensOf(text), Math.round(4200 / CHARS_PER_TOKEN));
  assert.equal(estimateTokensOf(text), 1000);
});

test('whitespace and punctuation cost what they cost — nothing is collapsed away first', () => {
  // The reason the estimate left words behind: a rule id, a path and a fenced block
  // are one "word" each and many tokens, so a counter that splits on whitespace reads
  // dense Markdown as a fraction of its real weight.
  const dense = '`packs/basics/worldRules/claude-md-length.mjs`';
  assert.equal(countChars(dense), dense.length);
  assert.ok(estimateTokensOf(dense) >= 10, 'one whitespace-delimited token, ten-odd real ones');
});

test('rounding coarsens the answer without changing what it counts', () => {
  assert.equal(estimateTokens(4200, 100), 1000);
  assert.equal(estimateTokens(430, 100), 100, 'to the hundred, for a sense of scale');
  assert.equal(estimateTokens(430), 102, 'and to the token where a short body would round to nothing');
});

test('nothing at all is zero, never a throw', () => {
  for (const nothing of [null, undefined, '']) {
    assert.equal(countChars(nothing), 0);
    assert.equal(estimateTokensOf(nothing), 0);
  }
});

test('the deprecated countWords alias answers characters, so an older packs/ copy still computes the corrected figure', () => {
  // A member can hold this engine beside a `packs/` copy one lane behind, whose only
  // use of the old name is `estimateTokens(countWords(text))`. The alias keeps that
  // composition answering what the current caller answers; anything else hands that
  // member a silently different number than the one this repo reports.
  const text = 'some prose, `an-id`, and a path/to/a/file.mjs\n'.repeat(120);
  assert.equal(estimateTokens(countWords(text)), estimateTokensOf(text));
});

